-- The arbiter index is partial (slug is not null), so the predicate has
-- to be repeated here for Postgres to recognise it.
on conflict (org_slug, slug) where slug is not null do nothing;

-- The eighth item from the standard set, in the place it belongs: an
-- annual acknowledgement with a signature against a document version,
-- rather than a checkbox on a log.
insert into staff.policy_docs
  (org_slug, key, version, title, category, summary, body_md, attestation,
   applies_to, renew_months, sort_order, published_at)
values
('afc', 'clinical-financial-separation', 1,
 'Separation of clinical judgement from billing', 'clinical',
 'Clinical decisions are made on clinical grounds, and nobody is asked to make them on any other.',
$md$
## The rule

What a patient needs is decided on clinical grounds. Not on their coverage,
not on what they can pay today, and not on what a service is worth to the
clinic.

## In practice

- Clinical staff do not quote prices, negotiate balances, or discuss what a
  visit will cost. Send those questions to the front desk — it protects the
  patient and it protects you.
- Front desk staff do not advise on what care someone needs, add a service to
  a visit, or discourage one. Collecting a copay is a separate act from
  deciding what is medically necessary, and the two conversations do not
  happen at once.
- A patient's ability to pay never changes the screening or stabilizing care
  they are offered.
- Nobody's compensation is tied to ordering more tests, more imaging, or more
  visits, and no one may ask you to order something for that reason.

## If you are asked anyway

If anyone asks you to change a clinical decision for a financial reason, or a
billing decision for a clinical one, say no and report it. Report it even if
the person asking outranks you — especially then. You will not be penalized
for a good-faith report, and this is exactly the situation the incident
reporting policy exists to catch.
$md$,
 'I understand that clinical decisions are made on clinical grounds alone, that I will not let a patient''s ability to pay change the care they are offered, and that I will report any request to do otherwise.',
 null, 12, 70, now())
on conflict (org_slug, key, version) do nothing;


-- ========== staff-security.sql ==========

-- ============================================================
-- STAFF SECURITY — second factor, domain restriction, revocation
--
-- Run AFTER supabase/staff-schema.sql. Idempotent; safe to re-run.
--
-- Three additions, each closing a hole that the module opened when it
-- stopped being an anonymous patient tool and started holding named
-- employee records:
--
--  1. GOOGLE HOSTED DOMAIN. "Sign in with Google" accepts any Google
--     account on earth. An invite typo, or an invite to a personal
--     address that later changes hands, is currently enough to get in.
--     When an org sets this, the ID token's `hd` claim must match or the
--     sign-in is refused before the invite is even looked at.
--
--  2. TOTP SECOND FACTOR. OAuth cannot tell us whether Google asked for a
--     second factor, and no ID token claim reports it — so 2FA that
--     depends on Google is 2FA we cannot verify or enforce. This one is
--     ours: enrolled here, checked here, required by role.
--
--  3. SESSION REVOCATION. Sessions are signed cookies with no server-side
--     store, which is why they are cheap — and why deactivating someone
--     did nothing to the session already in their pocket. Every session
--     now carries the epoch it was issued at; bumping a user's epoch
--     invalidates every session they hold, everywhere, on their next
--     request.
-- ============================================================

-- ---------- org policy ----------

-- e.g. 'buchmedical.com'. Null means no restriction — any Google account
-- may sign in provided it has an invite, which is the state an org starts
-- in before it has Workspace.
alter table staff.orgs add column if not exists google_hosted_domain text;

-- Which roles must hold a second factor. Defaults to everyone with
-- authority over other people's records; an org can widen it to all staff.
do $$ begin
  alter table staff.orgs add column mfa_required_roles staff.user_role[] not null
    default array['platform_super_admin','org_admin','clinical_lead']::staff.user_role[];
exception when duplicate_column then null;
end $$;

-- ---------- per-user second factor ----------

-- Base32, as the authenticator app expects it. Stored rather than hashed
-- because TOTP verification needs the secret itself — there is no
-- one-way form of it, which is exactly why a leak of this column is a
-- serious event and why it is never sent to the client after enrollment.
alter table staff.users add column if not exists totp_secret text;
alter table staff.users add column if not exists totp_confirmed_at timestamptz;

-- The last time step accepted for this user. A TOTP code stays valid for
-- its whole window, so without this, a code shoulder-surfed or captured
-- in transit can be replayed within the same 30 seconds.
alter table staff.users add column if not exists totp_last_step bigint;

-- ---------- revocation ----------

-- Bumped to invalidate every session this user holds. A session presents
-- the epoch it was minted with; anything older is refused.
alter table staff.users add column if not exists session_epoch integer not null default 0;

-- Deactivating someone must also cut their live session. Doing it in a
-- trigger rather than in the route handler means it holds for every path
-- that ever sets active = false — an admin screen, a script, a psql
-- session at 2am.
create or replace function staff.revoke_on_deactivate()
returns trigger language plpgsql as $$
begin
  if old.active and not new.active then
    new.session_epoch := old.session_epoch + 1;
  end if;
  return new;
end $$;

drop trigger if exists staff_users_revoke_on_deactivate on staff.users;
create trigger staff_users_revoke_on_deactivate
  before update of active on staff.users
  for each row execute function staff.revoke_on_deactivate();

-- ---------- what a session check reads ----------
--
-- One row, by id, on every staff request. It is deliberately a fresh read
-- rather than something cached: the entire value of a kill switch is that
-- it takes effect on the next request, and a 60-second cache would mean a
-- 60-second window in which a just-fired employee still has access.
create or replace view staff.session_checks
with (security_invoker = true) as
select id, org_slug, role, active, session_epoch,
       (totp_confirmed_at is not null) as mfa_enrolled
  from staff.users;

grant select on staff.session_checks to staff_app;


-- ========== staff-single-domain.sql ==========

-- ============================================================
-- SINGLE-DOMAIN STAFF SIGN-IN
--
-- Run AFTER supabase/staff-security.sql. Idempotent.
--
-- The staff area used to live at <org>.urgentcare.chat/staff, which meant
-- the hostname told us which org a request belonged to before we had a
-- session. That was a genuinely good property — a stale cookie could not
-- choose an org — but it cost one Google OAuth redirect URI and one
-- manually-added Vercel domain PER CUSTOMER, which makes self-serve
-- signup impossible.
--
-- Now everyone signs in at urgentcare.chat/staff and the org comes from
-- the person's own row, re-read on every request. Tenant subdomains stay
-- for white-label PATIENT portals, where branding is the point.
--
-- THE CHICKEN AND EGG: sign-in has to find which org an email belongs to
-- BEFORE it can set the org context that RLS needs. There is no way to
-- scope that lookup, because "which scope" is the question being asked.
--
-- So it is one SECURITY DEFINER function, deliberately as narrow as it
-- can be:
--   - takes an email, returns at most 2 rows of (org_slug, role)
--   - returns nothing else: no names, no ids, no other columns
--   - the second row exists only so the caller can DETECT ambiguity and
--     refuse, rather than silently picking an org for someone
-- It is the single place in this schema that reads across orgs, and it
-- is the reason it gets this much comment.
-- ============================================================

create or replace function staff.resolve_signin(p_email text, p_google_sub text)
returns table (org_slug text, member_role staff.user_role, existing boolean)
language sql
security definer
-- Pinned so a search_path an attacker controls cannot shadow the tables
-- this function reads. Mandatory for SECURITY DEFINER; easy to forget.
set search_path = pg_catalog, public
as $$
  -- An existing member wins over any invite: someone already onboarded
  -- keeps their org and their current role, and a later invite to a
  -- different org must not silently move them.
  select u.org_slug, u.role, true
    from staff.users u
   where u.active
     and (u.google_sub = p_google_sub or lower(u.email) = lower(p_email))
   limit 2
$$;

create or replace function staff.resolve_invite(p_email text)
returns table (org_slug text, member_role staff.user_role)
language sql
security definer
set search_path = pg_catalog, public
as $$
  select i.org_slug, i.role
    from staff.org_invites i
   where i.revoked_at is null
     and (lower(i.email) = lower(p_email)
          or lower(i.email_domain) = lower(split_part(p_email, '@', 2)))
   -- An invite addressed to this person beats a blanket domain invite.
   order by (i.email is not null) desc
   limit 2
$$;

-- Executable by the app role and nobody else. REVOKE from public first,
-- because SECURITY DEFINER functions are executable by public by default
-- and that default is how these leak.
revoke all on function staff.resolve_signin(text, text) from public;
revoke all on function staff.resolve_invite(text) from public;
grant execute on function staff.resolve_signin(text, text) to staff_app;
grant execute on function staff.resolve_invite(text) to staff_app;


-- ========== staff-billing.sql ==========

-- ============================================================
-- BILLING, AND THE REGULATORY IDENTITY OF A CLINIC
--
-- Run AFTER supabase/staff-single-domain.sql. Idempotent.
--
-- THE RULE THAT SHAPES THIS FILE: a lapsed subscription must never lock a
-- clinic out of its own compliance records. Those records are the
-- evidence they produce for a surveyor. Turning a billing hiccup into
-- "we couldn't produce our logs" would make this product the cause of the
-- exact catastrophe it is sold to prevent.
--
-- So non-payment is READ-ONLY, not lockout: everything already recorded
-- stays readable and exportable forever; only new operational entries
-- stop. That is enough commercial pressure — a clinic that cannot run
-- today's shift will notice — without ever holding their evidence hostage.
-- ============================================================

alter table staff.orgs add column if not exists stripe_customer_id     text;
alter table staff.orgs add column if not exists stripe_subscription_id text;
-- Mirrors Stripe's own vocabulary so the value is diffable against the
-- dashboard when something looks wrong: active | trialing | past_due |
-- canceled | unpaid | incomplete.
alter table staff.orgs add column if not exists subscription_status text not null default 'active';
alter table staff.orgs add column if not exists is_read_only boolean not null default false;
alter table staff.orgs add column if not exists billing_email text;
alter table staff.orgs add column if not exists read_only_since timestamptz;

create unique index if not exists staff_orgs_stripe_customer
  on staff.orgs (stripe_customer_id) where stripe_customer_id is not null;

-- ---------- regulatory identity ----------
--
-- Deliberately on staff.orgs and NOT on public.tenants. public.tenants
-- decides what colour a clinic's patient chat bubbles are; this is their
-- CLIA certificate. Mixing the two would put regulatory identifiers in the
-- table the anonymous patient side reads.
alter table staff.orgs add column if not exists site_id               text;
alter table staff.orgs add column if not exists legal_entity          text;
alter table staff.orgs add column if not exists address_line1         text;
alter table staff.orgs add column if not exists city                  text;
alter table staff.orgs add column if not exists state                 text;
alter table staff.orgs add column if not exists postal_code           text;
alter table staff.orgs add column if not exists phone                 text;
alter table staff.orgs add column if not exists clia_number           text;
alter table staff.orgs add column if not exists pa_dep_number         text;
alter table staff.orgs add column if not exists npi                   text;
alter table staff.orgs add column if not exists medical_director_name text;

create unique index if not exists staff_orgs_site_id
  on staff.orgs (site_id) where site_id is not null;

-- ---------- staff currency, not staff identity ----------
--
-- Expiry dates only. No date of birth, no licence numbers, no DEA
-- registration.
--
-- "Are all my medical assistants current on BLS?" is a real compliance
-- question and needs a DATE. "What is Jessica's licence number?" is not a
-- question this system has to answer, and storing the answer next to a
-- list of which controlled substances are on site and in what quantity
-- would make one leaked table an identity-theft kit and a
-- prescription-fraud enabler at the same time.
alter table staff.users add column if not exists bls_expires_on     date;
alter table staff.users add column if not exists license_expires_on date;
alter table staff.users add column if not exists arrt_expires_on    date;

-- What is expiring, and when, for everyone in an org. security_invoker so
-- it reads under the caller's RLS — see the note in staff-onboarding.sql.
create or replace view staff.credential_status
with (security_invoker = true) as
select
  u.id as user_id, u.org_slug, u.email, u.legal_name, u.role,
  c.kind, c.expires_on,
  (c.expires_on < current_date)                          as expired,
  (c.expires_on between current_date and current_date + 60) as expiring_soon
from staff.users u
cross join lateral (
  values ('BLS/CPR', u.bls_expires_on),
         ('Licence', u.license_expires_on),
         ('ARRT',    u.arrt_expires_on)
) as c(kind, expires_on)
where u.active and c.expires_on is not null;

grant select on staff.credential_status to staff_app;

-- ---------- the gate ----------
--
-- Read-only is enforced HERE, not only in a route handler. A trigger
-- cannot be forgotten by a future endpoint, an import script, or a
-- background job the way an `if` statement can.
create or replace function staff.reject_when_read_only()
returns trigger language plpgsql as $$
declare ro boolean;
begin
  select is_read_only into ro from staff.orgs where slug = new.org_slug;
  if ro then
    raise exception 'read_only: % is in read-only mode; existing records stay readable and exportable', new.org_slug
      using errcode = 'check_violation';
  end if;
  return new;
end $$;

drop trigger if exists staff_responses_read_only on staff.form_responses;
create trigger staff_responses_read_only
  before insert on staff.form_responses
  for each row execute function staff.reject_when_read_only();

-- NOTE what is NOT gated: staff.attestations.
--
-- Signing a policy is part of somebody's employment record, not the
-- clinic's operational output. Blocking it during a lapse would punish an
-- employee for their employer's card failing, and would leave a real
-- compliance hole — an unsigned HIPAA acknowledgement — as the
-- consequence. Reading is never gated anywhere.

-- ---------- webhook replay protection ----------
--
-- Stripe retries a webhook until it gets a 2xx, and a retry after a
-- partial failure would otherwise re-run whatever the first attempt did.
-- Recording the event id first makes every handler idempotent for free:
-- the insert conflicts and the handler returns early.
create table if not exists staff.stripe_events (
  id           text primary key,
  type         text not null,
  received_at  timestamptz not null default now()
);

grant select, insert on staff.stripe_events to staff_app;
-- Not org-scoped: a Stripe event arrives before we know which org it is
-- about, and it holds nothing but an id and a type.
alter table staff.stripe_events enable row level security;
drop policy if exists staff_stripe_events_app on staff.stripe_events;
create policy staff_stripe_events_app on staff.stripe_events for all using (true) with check (true);

-- Provisioning a brand-new org from a checkout, before any org context
-- exists. Same reasoning as staff.resolve_signin: this is a bootstrap
-- that cannot be scoped, so it is narrow, SECURITY DEFINER, pinned
-- search_path, and revoked from public.
create or replace function staff.provision_org(
  p_slug text, p_name text, p_customer text, p_subscription text, p_email text
) returns text
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare final_slug text := p_slug; n int := 1;
begin
  -- Already provisioned for this Stripe customer: return the existing org
  -- rather than making a second one on a retry.
  select slug into final_slug from staff.orgs where stripe_customer_id = p_customer;
  if found then return final_slug; end if;

  final_slug := p_slug;
  while exists (select 1 from staff.orgs where slug = final_slug) loop
    n := n + 1;
    final_slug := p_slug || '-' || n;
  end loop;

  insert into staff.orgs (slug, name, plan, stripe_customer_id,
                          stripe_subscription_id, subscription_status,
                          is_read_only, billing_email)
  values (final_slug, p_name, 'stripe', p_customer, p_subscription,
          'active', false, p_email);

  -- The person who paid is the first administrator. Without this they
  -- would complete checkout and have nothing to sign into.
  insert into staff.org_invites (org_slug, email, role)
  values (final_slug, lower(p_email), 'org_admin');

  return final_slug;
end $$;

revoke all on function staff.provision_org(text, text, text, text, text) from public;
grant execute on function staff.provision_org(text, text, text, text, text) to staff_app;


-- ========== staff-trial.sql ==========

-- ============================================================
-- NO-CREDIT-CARD TRIALS
--
-- Run AFTER supabase/staff-billing.sql. Idempotent.
--
-- "Start a 14-day trial, no credit card" is the conversion mechanism, and
-- it needs an org to exist BEFORE Stripe has ever heard of the customer.
--
-- Expiry is COMPUTED, NOT SCHEDULED. A nightly job that flips expired
-- trials to read-only is a job that can fail silently and hand out free
-- months, or fire twice and read-only somebody who just paid. A trial is
-- over when the date says so, evaluated on read.
-- ============================================================

alter table staff.orgs add column if not exists trial_ends_on date;

-- The single source of truth for "can this clinic file new entries".
-- is_read_only covers billing state; this adds the trial clock. Used by
-- the trigger and by the UI so they cannot disagree.
create or replace function staff.org_is_read_only(p_slug text)
returns boolean
language sql stable as $$
  select coalesce(
    o.is_read_only
    or (o.subscription_status = 'trialing'
        and o.trial_ends_on is not null
        and o.trial_ends_on < current_date),
    false)
  from staff.orgs o where o.slug = p_slug
$$;

-- Repoint the gate at it. Same trigger, same table, one definition of the
-- rule now instead of two.
create or replace function staff.reject_when_read_only()
returns trigger language plpgsql as $$
begin
  if staff.org_is_read_only(new.org_slug) then
    raise exception 'read_only: % is in read-only mode; existing records stay readable and exportable', new.org_slug
      using errcode = 'check_violation';
  end if;
  return new;
end $$;

-- Provisioning a trial, before any org context exists — same bootstrap
-- problem and same narrow SECURITY DEFINER treatment as provision_org.
--
-- One trial per email, ever. Not airtight against someone with many
-- addresses, and not meant to be: the cost of a spare empty org is a row,
-- and anything stricter would block a real clinic whose manager typo'd
-- their address the first time.
create or replace function staff.provision_trial(
  p_slug text, p_name text, p_email text, p_days int default 14
) returns text
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare final_slug text; n int := 1;
begin
  select org_slug into final_slug
    from staff.org_invites where lower(email) = lower(p_email) limit 1;
  if found then return final_slug; end if;

  final_slug := p_slug;
  while exists (select 1 from staff.orgs where slug = final_slug) loop
    n := n + 1;
    final_slug := p_slug || '-' || n;
  end loop;

  insert into staff.orgs (slug, name, plan, subscription_status,
                          is_read_only, trial_ends_on, billing_email)
  values (final_slug, p_name, 'trial', 'trialing',
          false, current_date + p_days, lower(p_email));

  insert into staff.org_invites (org_slug, email, role)
  values (final_slug, lower(p_email), 'org_admin');

  return final_slug;
end $$;

revoke all on function staff.provision_trial(text, text, text, int) from public;
grant execute on function staff.provision_trial(text, text, text, int) to staff_app;
grant execute on function staff.org_is_read_only(text) to staff_app;


-- ========== staff-obligations.sql ==========

-- ============================================================
-- THE OBLIGATIONS REGISTER
--
-- Run AFTER supabase/staff-trial.sql. Idempotent; safe to re-run.
--
-- WHAT THIS IS FOR, AND WHY THE REST OF THE MODULE DIDN'T ALREADY COVER IT
-- ----------------------------------------------------------------------
-- The module has two shapes of record and neither one is a deadline:
--
--   staff.attestations  — this PERSON read this document, once.
--   staff.form_responses — this TASK was done on this SHIFT, over and over.
--
-- Missing was the third: this ORGANIZATION owes this specific thing by
-- this specific date, and someone has to be the one who owes it. A risk
-- analysis due Sept 25, a certificate that expires, a drill nobody has
-- run this year. Those live in an inbox or a manager's head, which is
-- exactly where they are when a surveyor asks for them and nobody can
-- find who was supposed to do it.
--
-- DERIVED STATUS, NOT STORED STATUS. Overdue is not a flag some job sets
-- overnight; it is `due_on < current_date`, evaluated on read. Same
-- reasoning as the trial clock in staff-trial.sql: a nightly job that
-- marks things overdue is a job that can fail silently, and the failure
-- looks exactly like "nothing is overdue".
--
-- NOT GATED BY READ-ONLY, deliberately. Logs stop when a subscription
-- lapses; obligations do not. A register is a deadline calendar with
-- evidence attached, and blocking it would mean a clinic misses a real
-- regulatory deadline because of a failed card — the precise harm the
-- read-only rule exists to avoid. What lapses is the daily workflow.
-- ============================================================

create table if not exists staff.obligations (
  id uuid primary key default gen_random_uuid(),
  org_slug text not null references staff.orgs(slug) on delete cascade,

  -- Stable identifier, so a recurring obligation keeps its identity
  -- across occurrences and the seed can be re-run without duplicating.
  -- Defaulted rather than nullable: a null key would exempt custom
  -- obligations from the uniqueness index below, which is where
  -- double-entry gets caught.
  key text not null default replace(gen_random_uuid()::text, '-', ''),

  title text not null,
  detail text,
  category text,
  -- The rule, where there is one. Printed next to the obligation so
  -- nobody has to take the app's word for why it exists.
  citation text,
  -- Where this deadline came from: a regulation, a franchise bulletin, an
  -- accreditation finding, a manager. A surveyor's first question about
  -- an item on a list is who put it there.
  source text,

  due_on date not null,

  -- Nullable on purpose. "Nobody owns this" is a real and important
  -- state, and the register shows it loudly rather than quietly
  -- defaulting the owner to whoever created the row.
  owner_id uuid references staff.users(id) on delete set null,

  -- null = one-off. Otherwise the next occurrence is created the moment
  -- this one is completed.
  repeat_months integer check (repeat_months is null or repeat_months between 1 and 60),

  completed_at timestamptz,
  completed_by uuid references staff.users(id),
  evidence_note text,

  -- Set only when reopening a completed obligation. The trigger below
  -- requires it and files the completion it displaced into history.
  reopen_reason text,

  -- Displaced completions. An obligation marked done by mistake is
  -- reopened, not erased.
  history jsonb not null default '[]'::jsonb,

  active boolean not null default true,
  created_at timestamptz not null default now(),
  created_by uuid references staff.users(id)
);

-- Done without saying what was done is not evidence. Same shape as the
-- corrective-action constraint on form_responses, and for the same
-- reason: the button can enforce it, but only the constraint makes it
-- true of every row regardless of how it got there.
do $$ begin
  alter table staff.obligations
    add constraint staff_obligation_needs_evidence
    check (
      completed_at is null
      or (evidence_note is not null and length(btrim(evidence_note)) >= 3)
    );
exception when duplicate_object then null;
end $$;

-- One occurrence of one obligation per due date. Catches the roll-forward
-- firing twice and a person filing the same annual review from two tabs.
create unique index if not exists staff_obligations_occurrence
  on staff.obligations (org_slug, key, due_on);

create index if not exists staff_obligations_open
  on staff.obligations (org_slug, due_on)
  where completed_at is null and active;

create index if not exists staff_obligations_owner
  on staff.obligations (org_slug, owner_id)
  where completed_at is null and active;

-- ============================================================
-- COMPLETIONS ARE SET-ONCE
--
-- A completion is evidence. Editing one in place would let today's
-- version of events overwrite the record of what was actually filed and
-- when, which is the property that makes the register worth showing to
-- anyone. Reopening is allowed — people mark the wrong row — but it costs
-- a reason and the displaced completion stays visible.
-- ============================================================

create or replace function staff.obligations_completion_guard()
returns trigger language plpgsql as $$
begin
  if old.completed_at is not null and new.completed_at is null then
    if new.reopen_reason is null or length(btrim(new.reopen_reason)) < 3 then
      raise exception 'reopen_reason required: reopening a completed obligation has to say why'
        using errcode = 'check_violation';
    end if;
    new.history := old.history || jsonb_build_object(
      'completed_at',  old.completed_at,
      'completed_by',  old.completed_by,
      'evidence_note', old.evidence_note,
      'reopened_at',   now(),
      'reason',        btrim(new.reopen_reason)
    );
    new.completed_by := null;
    new.evidence_note := null;
    return new;
  end if;

  if old.completed_at is not null
     and new.completed_at is not null
     and (new.completed_at <> old.completed_at
          or new.evidence_note is distinct from old.evidence_note) then
    raise exception 'a recorded completion cannot be edited; reopen it and complete it again'
      using errcode = 'check_violation';
  end if;

  -- A fresh completion clears any reason left over from a previous
  -- reopen, so the column always describes the current state.
  if old.completed_at is null and new.completed_at is not null then
    new.reopen_reason := null;
  end if;

  -- The due date of a completed obligation is history: it is the half of
  -- the record that answers "was it done on time". Moving it afterwards
  -- would quietly turn a late completion into a punctual one, and would
  -- disagree with the next occurrence, which was already dated from the
  -- original. Reopen it if the date was genuinely wrong.
  if old.completed_at is not null and new.completed_at is not null
     and new.due_on <> old.due_on then
    raise exception 'the due date of a completed obligation cannot be moved; reopen it first'
      using errcode = 'check_violation';
  end if;

  return new;
end $$;

drop trigger if exists staff_obligations_guard on staff.obligations;
create trigger staff_obligations_guard
  before update on staff.obligations
  for each row execute function staff.obligations_completion_guard();

-- ============================================================
-- RECURRENCE
--
-- The next occurrence is dated from the DUE date, not the completion
-- date. An annual review done three weeks late is still due the same week
-- next year; dating it from completion would walk every recurring
-- deadline later every cycle until an annual obligation quietly became a
-- fourteen-month one.
-- ============================================================

create or replace function staff.obligations_roll_forward()
returns trigger language plpgsql as $$
declare next_due date;
begin
  if new.repeat_months is null or not new.active then return null; end if;

  next_due := (new.due_on + make_interval(months => new.repeat_months))::date;

  -- A badly overdue recurring item would otherwise create its next
  -- occurrence already in the past. Walk forward to the first one that
  -- hasn't happened yet.
  while next_due < current_date loop
    next_due := (next_due + make_interval(months => new.repeat_months))::date;
  end loop;

  insert into staff.obligations
    (org_slug, key, title, detail, category, citation, source,
     due_on, owner_id, repeat_months, created_by)
  values
    (new.org_slug, new.key, new.title, new.detail, new.category,
     new.citation, new.source, next_due, new.owner_id, new.repeat_months,
     new.completed_by)
  on conflict (org_slug, key, due_on) do nothing;

  return null;
end $$;

drop trigger if exists staff_obligations_roll on staff.obligations;
create trigger staff_obligations_roll
  after update on staff.obligations
  for each row
  when (old.completed_at is null and new.completed_at is not null)
  execute function staff.obligations_roll_forward();

-- ============================================================
-- ROW-LEVEL SECURITY
--
-- Same shape as every other org-scoped table. See staff-schema.sql.
-- ============================================================

alter table staff.obligations enable row level security;
alter table staff.obligations force row level security;

drop policy if exists staff_org_isolation on staff.obligations;
create policy staff_org_isolation on staff.obligations
  for all
  using (staff.is_super_admin() or org_slug = staff.current_org())
  with check (staff.is_super_admin() or org_slug = staff.current_org());

grant select, insert, update on staff.obligations to staff_app;
-- An obligation that turns out not to apply is deactivated, not deleted,
-- so the register keeps the fact that somebody decided it didn't apply.
--
-- The REVOKE is the line that makes that true, and it is not redundant
-- with the GRANT above. staff-schema.sql sets ALTER DEFAULT PRIVILEGES
-- granting delete on every future table in this schema, so this table
-- arrived with DELETE already held and granting three verbs took none of
-- it away. Tested: staff_app deleted a seeded obligation outright before
-- this line existed.
revoke delete on staff.obligations from staff_app;

-- ============================================================
-- THE REGISTER
--
-- security_invoker so it reads under the caller's org context rather than
-- the view owner's — without it a view over an RLS-protected table
-- returns every org's rows. See the same note in staff-onboarding.sql.
-- ============================================================

create or replace view staff.obligation_register
with (security_invoker = true) as
select
  o.id,
  o.org_slug,
  o.key,
  o.title,
  o.detail,
  o.category,
  o.citation,
  o.source,
  o.due_on,
  o.owner_id,
  o.repeat_months,
  o.completed_at,
  o.completed_by,
  o.evidence_note,
  o.history,
  o.created_at,
  (o.due_on - current_date)                      as days_out,
  jsonb_array_length(o.history) > 0              as was_reopened,
  case
    when o.completed_at is not null then 'done'
    when o.due_on < current_date    then 'overdue'
    when o.due_on <= current_date + 30 then 'due_soon'
    else 'scheduled'
  end                                            as status,
  ow.legal_name                                  as owner_name,
  ow.email                                       as owner_email,
  ow.active                                      as owner_active,
  cb.legal_name                                  as completed_by_name,
  cb.email                                       as completed_by_email
from staff.obligations o
left join staff.users ow on ow.id = o.owner_id
left join staff.users cb on cb.id = o.completed_by
where o.active;

grant select on staff.obligation_register to staff_app;

-- One number for the dashboard, so the landing screen doesn't pull the
-- whole register to count two things.
create or replace view staff.obligation_summary
with (security_invoker = true) as
select
  org_slug,
  count(*) filter (where status = 'overdue')::int  as overdue,
  count(*) filter (where status = 'due_soon')::int as due_soon,
  count(*) filter (where status <> 'done' and owner_id is null)::int as unowned,
  min(due_on) filter (where status <> 'done')      as next_due_on
from staff.obligation_register
group by org_slug;

grant select on staff.obligation_summary to staff_app;


-- ========== staff-obligations-seed.sql ==========

-- ============================================================
-- THE STARTING REGISTER
--
-- Run AFTER supabase/staff-obligations.sql. Idempotent.
--
-- An empty register is worse than no register: it reads as "nothing is
-- owed" when what it means is "nobody has typed anything in yet". So a
-- new clinic starts with the recurring obligations that apply to
-- essentially every US urgent care, dated, and unowned — because unowned
-- is the honest starting state and the register shows it in red.
--
-- ACCURACY NOTE, and please read it before trusting the dates.
--
-- Where a regulation states a frequency, the citation is exact and the
-- interval is the regulation's own: the OSHA bloodborne pathogens plan
-- really does say "at least annually", and the fire extinguisher check
-- really is an annual maintenance check.
--
-- Where a regulation requires something but states NO frequency — most of
-- the HIPAA items — the interval here is convention, not law, and the
-- detail text says so. Annual is what auditors expect and what the
-- Security Rule's "review periodically" is universally read to mean, but
-- an obligation that claims a rule says something it doesn't is worse
-- than no obligation at all, because the first person to check loses
-- confidence in every other row.
--
-- Items with no citation are practice standards, marked as such.
--
-- The list is a starting point for an administrator to correct, not a
-- compliance opinion. Intervals, applicability, and state-level additions
-- differ by state, by NAICS code, by payer, and by accreditation body.
-- ============================================================

create or replace function staff.seed_obligations(p_slug text)
returns integer
language plpgsql as $$
declare n integer;
begin
  with library (key, title, detail, category, citation, source,
                repeat_months, fixed_month, fixed_day, offset_days) as (
    values
      ('hipaa-sra',
       'HIPAA Security Risk Analysis',
       'An accurate and thorough assessment of the risks to electronic PHI, documented. The rule requires the analysis and requires it to be reviewed and updated as conditions change; it does not name an interval. Annual is the convention and what an OCR investigator will expect to see dated.',
       'HIPAA', '45 CFR 164.308(a)(1)(ii)(A)', 'HIPAA Security Rule', 12, null, null, 30),

      ('hipaa-policy-review',
       'HIPAA policies and procedures review',
       'Review the documented security policies and procedures and update them where the practice has changed. The rule says "periodically"; annual is the convention.',
       'HIPAA', '45 CFR 164.316(b)(2)(iii)', 'HIPAA Security Rule', 12, null, null, 45),

      ('hipaa-training',
       'Workforce HIPAA privacy and security training',
       'Training for every member of the workforce, including new hires within a reasonable period. Neither rule names an interval for refresher training; annual is the convention. Individual acknowledgements are signed in this app under My record — this row is the organization-level evidence that the session happened.',
       'HIPAA', '45 CFR 164.530(b)(1); 45 CFR 164.308(a)(5)', 'HIPAA Privacy and Security Rules', 12, null, null, 60),

      ('hipaa-baa-review',
       'Business Associate Agreement review',
       'Confirm a current signed BAA exists for every vendor that touches PHI — EHR, billing, transcription, shredding, IT support, cloud backup. No stated interval; annual review is the convention, and the moment a vendor changes is the other time to do it.',
       'HIPAA', '45 CFR 164.308(b)(1); 45 CFR 164.502(e)', 'HIPAA Privacy and Security Rules', 12, null, null, 75),

      ('osha-ecp-review',
       'Bloodborne pathogens Exposure Control Plan review',
       'The plan must be reviewed and updated at least annually, and the review must document consideration of safer engineered sharps devices. This one is annual in the regulation itself, not by convention.',
       'OSHA', '29 CFR 1910.1030(c)(1)(iv)', 'OSHA Bloodborne Pathogens Standard', 12, null, null, 21),

      ('osha-bbp-training',
       'Bloodborne pathogens training',
       'Annual training for every employee with occupational exposure, within one year of their previous training. Annual in the regulation.',
       'OSHA', '29 CFR 1910.1030(g)(2)(ii)', 'OSHA Bloodborne Pathogens Standard', 12, null, null, 35),

      ('osha-hazcom',
       'Hazard communication program and SDS review',
       'Chemical inventory current, safety data sheets on hand and accessible during every shift, labels intact. No stated review interval; annual is the convention.',
       'OSHA', '29 CFR 1910.1200', 'OSHA Hazard Communication Standard', 12, null, null, 90),

      ('osha-300a',
       'Post OSHA Form 300A summary',
       'Post the annual injury and illness summary by February 1 and keep it up until April 30. APPLICABILITY VARIES: employers with ten or fewer employees and certain partially exempt industry codes are excused from routine recordkeeping, and whether an urgent care center is exempt depends on the NAICS code it operates under. Confirm which applies to this site before treating this as due.',
       'OSHA', '29 CFR 1904.32', 'OSHA recordkeeping', 12, 2, 1, null),

      ('fire-extinguisher',
       'Fire extinguisher annual maintenance check',
       'An annual maintenance check on every portable extinguisher, with the date recorded on the tag and the record kept for a year after the tag is replaced. Annual in the regulation.',
       'Life safety', '29 CFR 1910.157(e)(3)', 'OSHA portable fire extinguishers', 12, null, null, 40),

      ('eyewash-annual',
       'Eyewash station annual performance evaluation',
       'A full performance evaluation of every plumbed eyewash — flow, pattern, temperature, duration. The weekly activation is a separate log in this app. OSHA requires suitable facilities without naming a test interval; the annual evaluation comes from ANSI Z358.1, the consensus standard OSHA cites.',
       'Life safety', '29 CFR 1910.151(c); ANSI Z358.1', 'OSHA medical services and first aid', 12, null, null, 50),

      ('clia-renewal',
       'CLIA certificate renewal',
       'Certificates run two years. The renewal notice arrives roughly six months out and is easy to lose. Waived testing performed on an expired certificate is unbillable and, depending on the state, unlawful.',
       'Laboratory', '42 CFR 493', 'CLIA', 24, null, null, 120),

      ('crash-cart-expiry',
       'Emergency medication and supply expiry review',
       'Every dated item on the crash cart and in the emergency kit — epinephrine, naloxone, atropine, IV fluids, defibrillator pads and battery. Monthly, because the failure mode is discovering the expiry during the emergency.',
       'Clinical', null, 'Practice standard', 1, null, null, 14),

      ('license-review',
       'Provider licence and credential expiry review',
       'Walk the roster: state licences, DEA registrations where applicable, BLS and ACLS cards, malpractice coverage, payer credentialing. Quarterly, so a lapse surfaces with time to renew rather than on the day someone is scheduled.',
       'Employment', null, 'Practice standard', 3, null, null, 28),

      ('vaccine-storage-review',
       'Vaccine storage and handling plan review',
       'Review the storage and handling plan and the emergency plan for a unit failure: where stock goes, who is called, how transport temperature is documented. The daily fridge temperatures are a separate log in this app; this is the plan behind them.',
       'Clinical', null, 'CDC Vaccine Storage and Handling Toolkit', 12, null, null, 65),

      ('flu-readiness',
       'Influenza season readiness',
       'Before the season starts: doses ordered, storage capacity confirmed, standing orders signed and current, staff vaccination offered and documented, billing set up for the new season codes.',
       'Clinical', null, 'Practice standard', 12, 9, 1, null),

      ('emergency-drill',
       'Emergency preparedness drill',
       'Run and document one drill — evacuation, power failure, or a medical emergency in the waiting room — with who took part and what it exposed. Not a federal requirement for a freestanding urgent care that is not a CMS-certified provider type; it is what an accreditation surveyor asks for and what a state inspector expects.',
       'Life safety', null, 'Practice standard', 12, null, null, 100)
  )
  insert into staff.obligations
    (org_slug, key, title, detail, category, citation, source, due_on, repeat_months)
  select
    p_slug, l.key, l.title, l.detail, l.category, l.citation, l.source,
    case
      -- Calendar-fixed deadlines land on their date: the next one that
      -- hasn't already passed.
      when l.fixed_month is not null then
        case
          when make_date(
                 extract(year from current_date)::int, l.fixed_month, l.fixed_day
               ) >= current_date
          then make_date(extract(year from current_date)::int, l.fixed_month, l.fixed_day)
          else make_date(extract(year from current_date)::int + 1, l.fixed_month, l.fixed_day)
        end
      -- Everything else is staggered rather than all dated today. Sixteen
      -- obligations due on the day you sign up is a register nobody
      -- opens twice.
      else current_date + l.offset_days
    end,
    l.repeat_months
  from library l
  -- Idempotent by key rather than by (key, due_on): re-running months
  -- later would compute different stagger dates and quietly file a second
  -- copy of everything.
  where not exists (
    select 1 from staff.obligations o
     where o.org_slug = p_slug and o.key = l.key
  );

  get diagnostics n = row_count;
  return n;
end $$;

grant execute on function staff.seed_obligations(text) to staff_app;

-- Every path that creates an org gets a register: provision_org from a
-- Stripe checkout, provision_trial from /start, and an insert typed by
-- hand. Hanging this off the table rather than editing each function
-- means a future fourth path cannot forget.
create or replace function staff.obligations_seed_new_org()
returns trigger language plpgsql as $$
begin
  perform staff.seed_obligations(new.slug);
  return null;
end $$;

drop trigger if exists staff_orgs_seed_obligations on staff.orgs;
create trigger staff_orgs_seed_obligations
  after insert on staff.orgs
  for each row execute function staff.obligations_seed_new_org();

-- Backfill any org that already exists.
do $$
declare o record;
begin
  for o in select slug from staff.orgs loop
    perform staff.seed_obligations(o.slug);
  end loop;
end $$;
